const songTitles = new Set();
const artists = new Set();
const albums = new Set();
for (const block of blocks) {
  artists.add(block.artist);
  if (block.album) albums.add(block.album);
  for (const song of block.songs) songTitles.add(song);
}

const targets = ['catalog/data/suggestion-pool.json', 'public/catalog/data/suggestion-pool.json'];
for (const path of targets) {
  const pool = JSON.parse(readFileSync(path, 'utf-8'));
  const existingSongs = new Set(pool.song_titles);
  const existingArtists = new Set(pool.artists);
  const existingAlbums = new Set(pool.albums);
  for (const s of songTitles) existingSongs.add(s);
  for (const a of artists) existingArtists.add(a);
  for (const a of albums) existingAlbums.add(a);
  pool.song_titles = [...existingSongs];
  pool.artists = [...existingArtists];
  pool.albums = [...existingAlbums];
  writeFileSync(path, JSON.stringify(pool, null, 2) + '\n', 'utf-8');
  console.log(`${path}: ${pool.song_titles.length} songs, ${pool.artists.length} artists, ${pool.albums.length} albums`);
}
console.log(`Added ${songTitles.size} new song titles, ${artists.size} new artists, ${albums.size} new albums (before existing-dedup)`);
